import csv
import io
import re


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        rows = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    def kind(value):
        value = value.strip()
        if not value:
            return "empty"
        if re.fullmatch(r"\d{1,4}[-/]\d{1,2}[-/]\d{1,4}", value):
            return "date"
        if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:\s*[APap][Mm])?", value):
            return "time"
        if re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", value):
            return "number"
        if value.lower() in ("nan", "inf", "-inf", "+inf", "infinity"):
            return "number"
        return "text"

    header = None
    if rows and len(rows[0]) == 3:
        first = rows[0]
        first_kinds = [kind(value) for value in first]
        if all(k in ("text", "empty") for k in first_kinds) and "text" in first_kinds:
            labels = {"date", "time", "datetime", "timestamp", "value", "reading", "measurement"}
            obvious = any(value.strip().lower() in labels for value in first)
            different = any(
                i < len(row) and first_kinds[i] == "text"
                and kind(row[i]) in ("date", "time", "number")
                for row in rows[1:11]
                for i in range(3)
            )
            if obvious or different:
                header = rows.pop(0)

    width = max([3, len(header) if header is not None else 0] + [len(row) for row in rows])
    columns = list(header) if header is not None else []
    while len(columns) < width:
        columns.append("column_{}".format(len(columns) + 1))
    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
